const webhookData = $input.first().json;
const data = webhookData.body;

console.log('📬 Received:', JSON.stringify(data, null, 2));

if (!data.source || (data.source !== 'email' && data.source !== 'webhook')) {
  console.log('⏭️ Skipping - wrong source');
  return [];
}

if (!data.creatorEmail) {
  console.log('⚠️ No email');
  return [];
}

const isStatusChange = !!(data.oldStatus && data.newStatus);

console.log('🔍 Status change:', isStatusChange);

const statusNames = {
  'triage': 'Triage',
  'todo': 'To Do',
  'in-progress': 'In Bearbeitung',
  'await-feedback': 'Feedback abwarten',
  'done': 'Erledigt'
};

const statusEmojis = {
  'triage': '🔍',
  'todo': '📋',
  'in-progress': '⚙️',
  'await-feedback': '⏳',
  'done': '✅'
};

if (isStatusChange) {
  const oldStatusFormatted = statusNames[data.oldStatus] || data.oldStatus;
  const newStatusFormatted = statusNames[data.newStatus] || data.newStatus;
  const statusEmoji = statusEmojis[data.newStatus] || '🔔';

  return {
    json: {
      taskId: data.taskId,
      taskTitle: data.taskTitle || 'Aufgabe',
      oldStatus: oldStatusFormatted,
      newStatus: newStatusFormatted,
      statusEmoji: statusEmoji,
      creatorEmail: data.creatorEmail,
      creatorName: data.creatorName || 'User',
      updatedBy: data.updatedBy || 'Team',
      formattedDate: new Date().toLocaleString('de-DE')
    }
  };
}

return [];

